import React from 'react';
import {
  AbsoluteFill,
  interpolate,
  spring,
  useCurrentFrame,
  useVideoConfig,
  Sequence,
  Easing,
} from 'remotion';

// 圆周角定理：圆周角等于其所对圆心角的一半
export const CircumferenceAngleTheorem: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // 圆心位置
  const centerX = width / 2;
  const centerY = height / 2;
  const radius = 200;

  // 时间段定义（以秒为单位）
  const INTRO_DURATION = 2;
  const DRAW_CIRCLE_DURATION = 1.5;
  const DRAW_POINTS_DURATION = 2;
  const DRAW_CENTRAL_ANGLE_DURATION = 2;
  const DRAW_INSCRIBED_ANGLE_DURATION = 2;
  const HIGHLIGHT_DURATION = 2;
  const PROOF_DURATION = 4;
  const CONCLUSION_DURATION = 2;

  // 累积时间点
  let currentTime = 0;
  const INTRO_START = currentTime;
  currentTime += INTRO_DURATION;
  const CIRCLE_START = currentTime;
  currentTime += DRAW_CIRCLE_DURATION;
  const POINTS_START = currentTime;
  currentTime += DRAW_POINTS_DURATION;
  const CENTRAL_ANGLE_START = currentTime;
  currentTime += DRAW_CENTRAL_ANGLE_DURATION;
  const INSCRIBED_ANGLE_START = currentTime;
  currentTime += DRAW_INSCRIBED_ANGLE_DURATION;
  const HIGHLIGHT_START = currentTime;
  currentTime += HIGHLIGHT_DURATION;
  const PROOF_START = currentTime;
  currentTime += PROOF_DURATION;
  const CONCLUSION_START = currentTime;

  // 固定点的位置（用角度定义）
  const pointAAngle = 180; // A点在左边
  const pointBAngle = 0; // B点在右边
  const pointCAngle = 60; // C点在圆周上

  // 计算点的坐标
  const getPointOnCircle = (angle: number) => ({
    x: centerX + radius * Math.cos((angle * Math.PI) / 180),
    y: centerY + radius * Math.sin((angle * Math.PI) / 180),
  });

  const pointA = getPointOnCircle(pointAAngle);
  const pointB = getPointOnCircle(pointBAngle);
  const pointC = getPointOnCircle(pointCAngle);

  // 计算角度（用于显示）
  const centralAngle = Math.abs(pointBAngle - pointAAngle);
  const inscribedAngle = centralAngle / 2;

  // 动画进度
  const introProgress = spring({
    frame: frame - INTRO_START * fps,
    fps,
    config: { damping: 200 },
  });

  const circleProgress = spring({
    frame: frame - CIRCLE_START * fps,
    fps,
    config: { damping: 200 },
  });

  const pointsProgress = spring({
    frame: frame - POINTS_START * fps,
    fps,
    config: { damping: 20, stiffness: 200 },
  });

  const centralAngleProgress = spring({
    frame: frame - CENTRAL_ANGLE_START * fps,
    fps,
    config: { damping: 200 },
  });

  const inscribedAngleProgress = spring({
    frame: frame - INSCRIBED_ANGLE_START * fps,
    fps,
    config: { damping: 200 },
  });

  const highlightProgress = interpolate(
    frame,
    [HIGHLIGHT_START * fps, (HIGHLIGHT_START + HIGHLIGHT_DURATION) * fps],
    [0, 1],
    {
      extrapolateRight: 'clamp',
      extrapolateLeft: 'clamp',
      easing: Easing.inOut(Easing.sin),
    }
  );

  const proofProgress = spring({
    frame: frame - PROOF_START * fps,
    fps,
    config: { damping: 200 },
  });

  const conclusionProgress = spring({
    frame: frame - CONCLUSION_START * fps,
    fps,
    config: { damping: 20 },
  });

  // 圆心角弧度的路径
  const centralArcPath = () => {
    const startAngle = (pointAAngle * Math.PI) / 180;
    const endAngle = (pointBAngle * Math.PI) / 180;
    const arcRadius = radius * 0.3;

    const x1 = centerX + arcRadius * Math.cos(startAngle);
    const y1 = centerY + arcRadius * Math.sin(startAngle);
    const x2 = centerX + arcRadius * Math.cos(endAngle);
    const y2 = centerY + arcRadius * Math.sin(endAngle);

    return `M ${x1} ${y1} A ${arcRadius} ${arcRadius} 0 1 1 ${x2} ${y2}`;
  };

  // 圆周角弧度的路径
  const inscribedArcPath = () => {
    const angleToA = Math.atan2(pointA.y - pointC.y, pointA.x - pointC.x);
    const angleToB = Math.atan2(pointB.y - pointC.y, pointB.x - pointC.x);
    const arcRadius = 50;

    const x1 = pointC.x + arcRadius * Math.cos(angleToA);
    const y1 = pointC.y + arcRadius * Math.sin(angleToA);
    const x2 = pointC.x + arcRadius * Math.cos(angleToB);
    const y2 = pointC.y + arcRadius * Math.sin(angleToB);

    const largeArcFlag = Math.abs(angleToB - angleToA) > Math.PI ? 1 : 0;

    return `M ${x1} ${y1} A ${arcRadius} ${arcRadius} 0 ${largeArcFlag} 1 ${x2} ${y2}`;
  };

  // 脉冲动画
  const pulseScale = 1 + 0.1 * Math.sin(highlightProgress * Math.PI * 4);

  return (
    <AbsoluteFill style={{ backgroundColor: '#0f172a' }}>
      {/* 标题 */}
      <Sequence from={INTRO_START * fps} premountFor={1 * fps}>
        <div
          style={{
            position: 'absolute',
            top: 60,
            left: 0,
            right: 0,
            textAlign: 'center',
            opacity: introProgress,
            transform: `translateY(${(1 - introProgress) * -20}px)`,
          }}
        >
          <h1
            style={{
              fontSize: 48,
              fontWeight: 'bold',
              color: '#f1f5f9',
              margin: 0,
              textShadow: '0 2px 10px rgba(59, 130, 246, 0.5)',
            }}
          >
            圆周角定理
          </h1>
          <p
            style={{
              fontSize: 24,
              color: '#94a3b8',
              margin: '10px 0 0 0',
            }}
          >
            Inscribed Angle Theorem
          </p>
        </div>
      </Sequence>

      {/* 主画布 */}
      <div
        style={{
          position: 'absolute',
          top: 0,
          left: 0,
          right: 0,
          bottom: 0,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
        }}
      >
        <svg
          width={width}
          height={height}
          style={{
            overflow: 'visible',
          }}
        >
          {/* 圆 */}
          <Sequence from={CIRCLE_START * fps} premountFor={1 * fps}>
            <circle
              cx={centerX}
              cy={centerY}
              r={radius * circleProgress}
              fill="none"
              stroke="#3b82f6"
              strokeWidth={3}
              opacity={0.8}
            />
          </Sequence>

          {/* 圆心 */}
          <Sequence from={CIRCLE_START * fps} premountFor={1 * fps}>
            <circle
              cx={centerX}
              cy={centerY}
              r={5 * circleProgress}
              fill="#3b82f6"
            />
            <text
              x={centerX}
              y={centerY - 15}
              textAnchor="middle"
              fill="#f1f5f9"
              fontSize={18}
              fontWeight="bold"
              opacity={circleProgress}
            >
              O
            </text>
          </Sequence>

          {/* 点 A, B, C */}
          <Sequence from={POINTS_START * fps} premountFor={1 * fps}>
            {/* 点 A */}
            <circle
              cx={pointA.x}
              cy={pointA.y}
              r={6 * pointsProgress}
              fill="#ef4444"
            />
            <text
              x={pointA.x - 20}
              y={pointA.y + 5}
              textAnchor="middle"
              fill="#f1f5f9"
              fontSize={20}
              fontWeight="bold"
              opacity={pointsProgress}
            >
              A
            </text>

            {/* 点 B */}
            <circle
              cx={pointB.x}
              cy={pointB.y}
              r={6 * pointsProgress}
              fill="#ef4444"
            />
            <text
              x={pointB.x + 20}
              y={pointB.y + 5}
              textAnchor="middle"
              fill="#f1f5f9"
              fontSize={20}
              fontWeight="bold"
              opacity={pointsProgress}
            >
              B
            </text>

            {/* 点 C */}
            <circle
              cx={pointC.x}
              cy={pointC.y}
              r={6 * pointsProgress}
              fill="#10b981"
            />
            <text
              x={pointC.x}
              y={pointC.y - 20}
              textAnchor="middle"
              fill="#f1f5f9"
              fontSize={20}
              fontWeight="bold"
              opacity={pointsProgress}
            >
              C
            </text>
          </Sequence>

          {/* 圆心角 ∠AOB */}
          <Sequence from={CENTRAL_ANGLE_START * fps} premountFor={1 * fps}>
            {/* OA 线段 */}
            <line
              x1={centerX}
              y1={centerY}
              x2={centerX + (pointA.x - centerX) * centralAngleProgress}
              y2={centerY + (pointA.y - centerY) * centralAngleProgress}
              stroke="#fbbf24"
              strokeWidth={2}
              opacity={0.8}
            />

            {/* OB 线段 */}
            <line
              x1={centerX}
              y1={centerY}
              x2={centerX + (pointB.x - centerX) * centralAngleProgress}
              y2={centerY + (pointB.y - centerY) * centralAngleProgress}
              stroke="#fbbf24"
              strokeWidth={2}
              opacity={0.8}
            />

            {/* 圆心角弧 */}
            <path
              d={centralArcPath()}
              fill="none"
              stroke="#fbbf24"
              strokeWidth={2}
              opacity={centralAngleProgress * 0.6}
            />

            {/* 圆心角标签 */}
            <text
              x={centerX}
              y={centerY + 80}
              textAnchor="middle"
              fill="#fbbf24"
              fontSize={22}
              fontWeight="bold"
              opacity={centralAngleProgress}
            >
              ∠AOB = {centralAngle}°
            </text>
          </Sequence>

          {/* 圆周角 ∠ACB */}
          <Sequence from={INSCRIBED_ANGLE_START * fps} premountFor={1 * fps}>
            {/* CA 线段 */}
            <line
              x1={pointC.x}
              y1={pointC.y}
              x2={pointC.x + (pointA.x - pointC.x) * inscribedAngleProgress}
              y2={pointC.y + (pointA.y - pointC.y) * inscribedAngleProgress}
              stroke="#a78bfa"
              strokeWidth={2}
              opacity={0.8}
            />

            {/* CB 线段 */}
            <line
              x1={pointC.x}
              y1={pointC.y}
              x2={pointC.x + (pointB.x - pointC.x) * inscribedAngleProgress}
              y2={pointC.y + (pointB.y - pointC.y) * inscribedAngleProgress}
              stroke="#a78bfa"
              strokeWidth={2}
              opacity={0.8}
            />

            {/* 圆周角弧 */}
            <path
              d={inscribedArcPath()}
              fill="none"
              stroke="#a78bfa"
              strokeWidth={2}
              opacity={inscribedAngleProgress * 0.6}
            />

            {/* 圆周角标签 */}
            <text
              x={pointC.x}
              y={pointC.y + 80}
              textAnchor="middle"
              fill="#a78bfa"
              fontSize={22}
              fontWeight="bold"
              opacity={inscribedAngleProgress}
            >
              ∠ACB = {inscribedAngle}°
            </text>
          </Sequence>

          {/* 高亮显示关系 */}
          <Sequence from={HIGHLIGHT_START * fps} premountFor={1 * fps}>
            {/* 圆心角高亮 */}
            <path
              d={centralArcPath()}
              fill="none"
              stroke="#fbbf24"
              strokeWidth={3 * pulseScale}
              opacity={0.9}
            />

            {/* 圆周角高亮 */}
            <path
              d={inscribedArcPath()}
              fill="none"
              stroke="#a78bfa"
              strokeWidth={3 * pulseScale}
              opacity={0.9}
            />
          </Sequence>
        </svg>
      </div>

      {/* 证明步骤 */}
      <Sequence from={PROOF_START * fps} premountFor={1 * fps}>
        <div
          style={{
            position: 'absolute',
            bottom: 80,
            left: 0,
            right: 0,
            display: 'flex',
            justifyContent: 'center',
            opacity: proofProgress,
            transform: `translateY(${(1 - proofProgress) * 20}px)`,
          }}
        >
          <div
            style={{
              backgroundColor: 'rgba(15, 23, 42, 0.9)',
              border: '2px solid #3b82f6',
              borderRadius: 16,
              padding: '20px 40px',
              maxWidth: 700,
            }}
          >
            <p
              style={{
                fontSize: 24,
                color: '#f1f5f9',
                margin: '0 0 10px 0',
                textAlign: 'center',
                fontWeight: 'bold',
              }}
            >
              定理
            </p>
            <p
              style={{
                fontSize: 20,
                color: '#94a3b8',
                margin: 0,
                textAlign: 'center',
                lineHeight: 1.6,
              }}
            >
              同弧所对的圆周角等于圆心角的一半
            </p>
            <p
              style={{
                fontSize: 28,
                color: '#3b82f6',
                margin: '15px 0 0 0',
                textAlign: 'center',
                fontWeight: 'bold',
              }}
            >
              ∠ACB = ½ ∠AOB
            </p>
          </div>
        </div>
      </Sequence>

      {/* 结论动画 */}
      <Sequence from={CONCLUSION_START * fps} premountFor={1 * fps}>
        <div
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundColor: 'rgba(15, 23, 42, 0.95)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            opacity: conclusionProgress,
          }}
        >
          <div
            style={{
              textAlign: 'center',
              transform: `scale(${0.8 + 0.2 * conclusionProgress})`,
            }}
          >
            <div
              style={{
                fontSize: 72,
                fontWeight: 'bold',
                background: 'linear-gradient(135deg, #3b82f6, #a78bfa)',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
                marginBottom: 20,
              }}
            >
              ∠ACB = ½ ∠AOB
            </div>
            <div
              style={{
                fontSize: 32,
                color: '#94a3b8',
              }}
            >
              圆周角定理得证
            </div>
          </div>
        </div>
      </Sequence>
    </AbsoluteFill>
  );
};

import { Composition } from 'remotion';
import { CircumferenceAngleTheorem } from './CircumferenceAngleTheorem';

export const RemotionRoot: React.FC = () => {
  return (
    <>
      <Composition
        id="CircumferenceAngleTheorem"
        component={CircumferenceAngleTheorem}
        durationInFrames={540}
        fps={30}
        width={1920}
        height={1080}
        defaultProps={{}}
      />
    </>
  );
};

